//! `proto-gen [--check]`: regenerates the device-plugin API bindings from the vendored proto. Run from the
//! repository root through `mise run proto:gen` or `mise run proto:check`.

use std::process::{Command, ExitCode};
use std::{env, fs};

const PROTO_ROOT: &str = "proto";
const PROTO: &str = "deviceplugin/v1beta1/api.proto";
const OUTPUT: &str = "crates/kvm-device-plugin/src/proto/v1beta1.rs";
const HEADER: &str = "\
// @generated by tools/proto-gen from proto/deviceplugin/v1beta1/api.proto. Do not edit; run `mise run proto:gen`.
// The proto is from Kubernetes v1.37.1, staging/src/k8s.io/kubelet/pkg/apis/deviceplugin/v1beta1/api.proto,
// licensed under the Apache License 2.0 (proto/LICENSE).

";

fn main() -> ExitCode {
    let check = match env::args().skip(1).collect::<Vec<_>>().as_slice() {
        [] => false,
        [flag] if flag == "--check" => true,
        _ => {
            eprintln!("usage: proto-gen [--check]");
            return ExitCode::from(2);
        },
    };
    match generate() {
        Ok(generated) if check => {
            if fs::read_to_string(OUTPUT).is_ok_and(|current| current == generated) {
                ExitCode::SUCCESS
            } else {
                eprintln!("proto-gen: {OUTPUT} is stale; run `mise run proto:gen`");
                ExitCode::FAILURE
            }
        },
        Ok(generated) => match fs::write(OUTPUT, generated) {
            Ok(()) => ExitCode::SUCCESS,
            Err(err) => {
                eprintln!("proto-gen: writing {OUTPUT}: {err}");
                ExitCode::FAILURE
            },
        },
        Err(err) => {
            eprintln!("proto-gen: {err}");
            ExitCode::FAILURE
        },
    }
}

/// Compiles the proto and returns the bindings, formatted with the repository's rustfmt settings.
fn generate() -> Result<String, Box<dyn std::error::Error>> {
    let out = tempfile::tempdir()?;
    let descriptors = protox::compile([PROTO], [PROTO_ROOT])?;
    tonic_prost_build::configure().out_dir(out.path()).compile_fds(descriptors)?;
    let path = out.path().join("v1beta1.rs");
    let body = fs::read_to_string(&path)?;
    fs::write(&path, format!("{HEADER}{body}"))?;
    let status = Command::new("rustfmt")
        .args(["--edition", "2024", "--config-path", "rustfmt.toml"])
        .arg(&path)
        .status()?;
    if !status.success() {
        return Err(format!("rustfmt failed: {status}").into());
    }
    Ok(fs::read_to_string(&path)?)
}
